package cm.capstone.donsang.service;
import cm.capstone.donsang.model.HistoriqueEmail; import cm.capstone.donsang.repository.HistoriqueEmailRepository; import lombok.RequiredArgsConstructor; import org.springframework.mail.SimpleMailMessage; import org.springframework.mail.javamail.MimeMessageHelper; import org.springframework.mail.javamail.JavaMailSender; import org.springframework.stereotype.Service; import org.thymeleaf.TemplateEngine; import org.thymeleaf.context.Context; import java.time.LocalDateTime; import static cm.capstone.donsang.model.Enums.*;
@Service @RequiredArgsConstructor public class EmailService {
 private final JavaMailSender sender; private final HistoriqueEmailRepository history; private final TemplateEngine templateEngine;
 public void send(String to,String subject,String body,TypeEmail type){sendInternal(to,subject,body,type,null,null);}
 public void sendActivation(String to,String nom,String code,LocalDateTime expiration){Context c=new Context();c.setVariable("nom",nom);c.setVariable("code",code);c.setVariable("expiration",expiration);String body=templateEngine.process("emails/code-activation",c);sendInternal(to,"Activation du compte — Réseau Don de Sang",body,TypeEmail.ACTIVATION,"text/html",body);}
 private void sendInternal(String to,String subject,String body,TypeEmail type,String subtype,String historyBody){var h=HistoriqueEmail.builder().destinataire(to).sujet(subject).contenu(historyBody==null?body:historyBody).type(type).dateEnvoi(LocalDateTime.now()).build();try{if(to!=null&&!to.isBlank()){if("text/html".equals(subtype)){var mm=sender.createMimeMessage();var mh=new MimeMessageHelper(mm,"UTF-8");mh.setTo(to);mh.setSubject(subject);mh.setText(body,true);sender.send(mm);}else{SimpleMailMessage m=new SimpleMailMessage();m.setTo(to);m.setSubject(subject);m.setText(body);sender.send(m);}}h.setStatut(StatutEmail.REUSSI);}catch(Exception e){h.setStatut(StatutEmail.ECHEC);}history.save(h);}
}
